using System;
using System.Collections.Generic;
using System.Threading.Tasks;
using UnityEngine;
using UnityEngine.EventSystems;
using UnityEngine.UI;
using Zenject;

/// <summary>
/// Plays the music loop and sound effects for game events and UI taps. Sounds are generated by
/// SoundSynth unless GameSettings has a clip for them. The on/off choices survive a progress reset.
/// </summary>
public class AudioController : IAudioController, IInitializable, ITickable, IDisposable
{
	private const string MusicKey = "audio.music";
	private const string SfxKey = "audio.sfx";

	// Loading a save completes research and fires other signals, which shouldn't make noise
	private const float StartupSilence = 1.5f;

	private readonly SignalBus signalBus;
	private readonly GameAudioSettings settings;

	private readonly Dictionary<SoundType, AudioClip> clips = new Dictionary<SoundType, AudioClip>();
	private readonly List<RaycastResult> raycastResults = new List<RaycastResult>();
	private GameObject audioObject;
	private AudioSource musicSource;
	private AudioSource sfxSource;
	private Task<float[]> musicTask;
	private float silentUntil;

	public bool MusicEnabled
	{
		get { return PlayerPrefs.GetInt(MusicKey, 1) == 1; }
		set
		{
			PlayerPrefs.SetInt(MusicKey, value ? 1 : 0);
			UpdateMusic();
		}
	}

	public bool SfxEnabled
	{
		get { return PlayerPrefs.GetInt(SfxKey, 1) == 1; }
		set { PlayerPrefs.SetInt(SfxKey, value ? 1 : 0); }
	}

	public AudioController(SignalBus signalBus, GameSettings gameSettings)
	{
		this.signalBus = signalBus;
		settings = gameSettings.AudioSettings;
	}

	public void Initialize()
	{
		silentUntil = Time.unscaledTime + StartupSilence;

		audioObject = new GameObject("Audio");
		musicSource = audioObject.AddComponent<AudioSource>();
		musicSource.loop = true;
		musicSource.playOnAwake = false;
		musicSource.volume = settings.MusicVolume;
		sfxSource = audioObject.AddComponent<AudioSource>();
		sfxSource.playOnAwake = false;
		sfxSource.volume = settings.SfxVolume;

		if (UnityEngine.Object.FindAnyObjectByType<AudioListener>() == null)
		{
			audioObject.AddComponent<AudioListener>();
		}

		foreach (SoundType type in Enum.GetValues(typeof(SoundType)))
		{
			SoundClip custom = Array.Find(settings.Sounds, s => s.Type == type && s.Clip != null);
			clips[type] = custom != null ? custom.Clip : SoundSynth.Create(type);
		}

		if (settings.Music != null)
		{
			musicSource.clip = settings.Music;
			UpdateMusic();
		}
		else
		{
			musicTask = Task.Run(() => SoundSynth.RenderMusic());
		}

		signalBus.Subscribe<PurchaseSignal>(OnPurchase);
		signalBus.Subscribe<ResourcesSellSignal>(OnSell);
		signalBus.Subscribe<RewardClaimedSignal>(OnClaim);
		signalBus.Subscribe<AsteroidDestroyedSignal>(OnAsteroidDestroyed);
		signalBus.Subscribe<ResearchCompletedSignal>(OnResearchCompleted);
	}

	public void Dispose()
	{
		signalBus.Unsubscribe<PurchaseSignal>(OnPurchase);
		signalBus.Unsubscribe<ResourcesSellSignal>(OnSell);
		signalBus.Unsubscribe<RewardClaimedSignal>(OnClaim);
		signalBus.Unsubscribe<AsteroidDestroyedSignal>(OnAsteroidDestroyed);
		signalBus.Unsubscribe<ResearchCompletedSignal>(OnResearchCompleted);

		if (audioObject != null)
		{
			UnityEngine.Object.Destroy(audioObject);
		}
	}

	public void Tick()
	{
		// The generated music is ready a moment after start
		if (musicTask != null && musicTask.IsCompleted)
		{
			if (musicTask.Status == TaskStatus.RanToCompletion)
			{
				musicSource.clip = SoundSynth.ToClip("Music", musicTask.Result);
				UpdateMusic();
			}

			musicTask = null;
		}

		if (Input.GetMouseButtonUp(0) && IsOverButton(Input.mousePosition))
		{
			Play(SoundType.Click);
		}
	}

	public void Play(SoundType type)
	{
		if (SfxEnabled && Time.unscaledTime >= silentUntil)
		{
			sfxSource.PlayOneShot(clips[type]);
		}
	}

	private void UpdateMusic()
	{
		if (musicSource == null || musicSource.clip == null)
		{
			return;
		}

		if (MusicEnabled && !musicSource.isPlaying)
		{
			musicSource.Play();
		}
		else if (!MusicEnabled)
		{
			musicSource.Stop();
		}
	}

	// Taps on any interactable UI control get a soft click
	private bool IsOverButton(Vector2 screenPosition)
	{
		EventSystem eventSystem = EventSystem.current;
		if (eventSystem == null)
		{
			return false;
		}

		raycastResults.Clear();
		eventSystem.RaycastAll(new PointerEventData(eventSystem) { position = screenPosition }, raycastResults);
		if (raycastResults.Count == 0)
		{
			return false;
		}

		Selectable selectable = raycastResults[0].gameObject.GetComponentInParent<Selectable>();
		return selectable != null && selectable.IsInteractable();
	}

	private void OnPurchase(PurchaseSignal signal)
	{
		if (!signal.Success)
		{
			Play(SoundType.Error);
			return;
		}

		Play(signal.Kind == PurchaseKind.Upgrade || signal.Kind == PurchaseKind.Room ? SoundType.Upgrade : SoundType.Purchase);
	}

	private void OnSell()
	{
		Play(SoundType.Sell);
	}

	private void OnClaim()
	{
		Play(SoundType.Claim);
	}

	private void OnAsteroidDestroyed()
	{
		Play(SoundType.Explosion);
	}

	private void OnResearchCompleted()
	{
		Play(SoundType.Unlock);
	}
}
